 * AC: @platform-renderer-trait ac-6 - Store per-platform hash in .render-hash-<platform>
 */
export async function writePlatformRenderHash(
  specDir: string,
  skillId: string,
  platform: string,
  hash: string
): Promise<void> {
  const hashPath = getPlatformRenderHashPath(specDir, skillId, platform);
