  kspec as kspecFull,
  setupTempFixtures,
  cleanupTempDir,
  initGitRepo,
} from './helpers/cli';
import {
  claudeCodeRenderer,
  getRenderer,
  getAllRenderers,
  registerRenderer,
  getPlatformRenderHashPath,
  readPlatformRenderHash,
  writePlatformRenderHash,
  checkPlatformSkillDrift,
  type PlatformRenderer,
  type PlatformRenderResult,
  type DriftStatus,
} from '../src/parser/skill-render';
