name: Task Work
description: Work on tasks
---
`);

    kspec(`skill import "${skillPath}" --origin core`, tempDir);

    const result = kspecJson<{ origin: string }>('skill get @task-work', tempDir);
    expect(result.origin).toBe('core');
  });

