describe('Skill CLI - skill delete', () => {
  let tempDir: string;

  beforeEach(async () => {
    tempDir = await setupTempFixtures();
    await initGitRepo(tempDir);

    // Create skills
    kspec('skill add --id my-skill --name "My Skill"', tempDir);
