    kspec('skill delete @standalone-skill --confirm', tempDir);

    // Verify it's gone
    list = kspecJson<Array<{ id: string }>>('skill list', tempDir);
    expect(list.some(s => s.id === 'standalone-skill')).toBe(false);
  });

  // AC: @skill-cli ac-8
