cat > /tmp/debug-render.test.ts << 'EOF'
import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import * as fs from 'node:fs/promises';
import * as path from 'node:path';
import {
  kspec as kspecFull,
  setupTempFixtures,
  cleanupTempDir,
  initGitRepo,
} from './tests/helpers/cli';

describe('Debug Render', () => {
  let tempDir: string;

  beforeEach(async () => {
    tempDir = await setupTempFixtures();
    await initGitRepo(tempDir);
  });

  afterEach(async () => {
    await cleanupTempDir(tempDir);
  });

  it('should render skill with modified meta', async () => {
    const result = kspecFull(
      'skill add --id test-skill --name "Test Skill" --description "A test skill" --platform claude-code',
      tempDir
    );
    console.log('skill add result:', result.stdout, result.stderr);

    // Read meta yaml before modification
    const metaPath = path.join(tempDir, 'kynetic.meta.yaml');
    const beforeMeta = await fs.readFile(metaPath, 'utf-8');
    console.log('BEFORE meta.yaml:\n', beforeMeta);

    // Modify
    let metaContent = beforeMeta.replace(
      /id: test-skill/,
      'id: test-skill\n  license: MIT'
    );
    await fs.writeFile(metaPath, metaContent, 'utf-8');

    const afterMeta = await fs.readFile(metaPath, 'utf-8');
    console.log('AFTER meta.yaml:\n', afterMeta);

    // Write content
    const skillMdPath = path.join(tempDir, 'skills', 'test-skill', 'SKILL.md');
    await fs.writeFile(skillMdPath, '# Test Skill\n\nContent.\n', 'utf-8');

    // Render
    const renderResult = kspecFull('skill render', tempDir);
    console.log('render result:', renderResult.stdout, renderResult.stderr);
  });
});
EOF
npm test -- --run /tmp/debug-render.test.ts 2>&1 | tail -60

