      let metaContent = await fs.readFile(metaPath, 'utf-8');
      metaContent = metaContent.replace(
        /id: case-skill/,
        'id: case-skill\n  platform_config:\n    claude_code:\n      disable_model_invocation: true\n      user_invocable: false'
