      );
      await fs.writeFile(metaPath, metaContent, 'utf-8');

      const skillMdPath = path.join(tempDir, 'skills', 'case-skill', 'SKILL.md');
      await fs.writeFile(skillMdPath, '# Case Skill\n', 'utf-8');

