describe('Debug YAML', () => {
  let tempDir: string;

  beforeEach(async () => {
    tempDir = await setupTempFixtures();
    await initGitRepo(tempDir);
  });

  afterEach(async () => {
    await cleanupTempDir(tempDir);
  });

  it('should debug allowed_tools YAML modification', async () => {
    kspecFull(
      'skill add --id tools-skill --name "Tools Skill" --description "A skill with tools" --platform claude-code',
      tempDir
    );

    // Read original meta.yaml
    const metaPath = path.join(tempDir, 'kynetic.meta.yaml');
    let metaContent = await fs.readFile(metaPath, 'utf-8');
    console.log('BEFORE:\n', metaContent.substring(metaContent.indexOf('tools-skill') - 10, metaContent.indexOf('tools-skill') + 200));

    // The skill already has an allowed_tools field that's empty, we need to replace that
    metaContent = metaContent.replace(
      /id: tools-skill\n/,
      'id: tools-skill\n    allowed_tools:\n      - Bash\n      - Read\n'
    );
    await fs.writeFile(metaPath, metaContent, 'utf-8');

    metaContent = await fs.readFile(metaPath, 'utf-8');
    console.log('AFTER:\n', metaContent.substring(metaContent.indexOf('tools-skill') - 10, metaContent.indexOf('tools-skill') + 300));

    // Write content
    const skillMdPath = path.join(tempDir, 'skills', 'tools-skill', 'SKILL.md');
    await fs.writeFile(skillMdPath, '# Tools Skill\n\nContent.\n', 'utf-8');

    // Render
    const renderResult = kspecFull('skill render', tempDir);
    console.log('render result:', renderResult.stdout, renderResult.stderr);
  });
});
