      const { codexRenderer, loadSkillContent } = await import('../src/parser/skill-render');
      const { loadKspecContext, loadMeta, resolveSkillRef } = await import('../src/parser/meta');

      // Create a skill
      kspecFull(
        'skill add --id codex-skill --name "Codex Skill" --description "A skill for Codex" --platform codex',
        tempDir
